"""Remove o passo de senha do cadastro de aluno e apaga senhas já coletadas.

O bot pedia RA + senha (sugerindo a do Portal do Aluno), mas não validava a
senha em lugar nenhum; ela ficava criptografada em UserProfile.utfpr_password
(removido em users.0009) e em TEXTO PURO no InteractionLog e no flow_data da
conversa. O login de empresa pelo WhatsApp também gravava a senha do portal no
InteractionLog. Esta migração:

- redige toda mensagem RECEBIDA logo depois de uma mensagem do bot que fala em
  "senha" (pedido de senha, "RA ou senha incorretos", senha de empresa);
- tira `temp_password` do flow_data;
- move quem estava parado no passo de senha para o passo de e-mail (ou para o
  menu, se não houver RA guardado);
- apaga as mensagens editáveis do passo de senha, que não são mais usadas.
"""

from django.db import migrations, models

REDACTED = "[conteúdo sensível omitido]"
_DEAD_MESSAGE_KEYS = [
    "login_prompt_password",
    "login_error",
    "auth.login_prompt_password",
    "auth.login_validating_credentials",
    "auth.login_error",
]


def _redact_logs(InteractionLog):
    last_sent_by_user: dict[int, str] = {}
    to_redact: list[int] = []
    rows = InteractionLog.objects.order_by("user_id", "created_at", "id").values_list(
        "id", "user_id", "message_type", "message_content"
    )
    for pk, user_id, kind, content in rows.iterator():
        if kind == "SENT":
            last_sent_by_user[user_id] = (content or "").lower()
        elif kind == "RECEIVED" and "senha" in last_sent_by_user.get(user_id, ""):
            if content != REDACTED:
                to_redact.append(pk)
    for start in range(0, len(to_redact), 500):
        InteractionLog.objects.filter(pk__in=to_redact[start : start + 500]).update(
            message_content=REDACTED
        )


def _clean_conversation_states(ConversationState):
    for state in ConversationState.objects.all().iterator():
        flow_data = dict(state.flow_data or {})
        changed = flow_data.pop("temp_password", None) is not None
        if state.current_action in ("login_step_password", "waiting_password"):
            state.current_action = "login_step_email" if flow_data.get("temp_ra") else None
            if state.current_action is None:
                flow_data = {}
            changed = True
        if changed:
            state.flow_data = flow_data
            state.save(update_fields=["current_action", "flow_data", "updated_at"])


def scrub_collected_passwords(apps, schema_editor):
    _redact_logs(apps.get_model("bot", "InteractionLog"))
    _clean_conversation_states(apps.get_model("bot", "ConversationState"))
    apps.get_model("bot", "BotMessage").objects.filter(key__in=_DEAD_MESSAGE_KEYS).delete()


